var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    var v = garage.variants[i];
    if (v.root == null) continue;
    if (i != 0 && i != garage.variants.Length - 1) continue;
    v.root.SetActive(true);
    var names = new System.Collections.Generic.List<string>();
    foreach (Renderer r in v.root.GetComponentsInChildren<Renderer>()) names.Add(r.gameObject.name);
    sb.AppendLine(i + " " + garage.specIds[i] + " renderers=" + names.Count + " names=" + string.Join(", ", names.ToArray()));
    v.root.SetActive(i == garage.selected);
}
Debug.Log("PROBE5 " + sb.ToString().Replace("\r", "").Replace("\n", " || "));
return sb.ToString();
